CREATE TABLE "nguoi_dung" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "email" varchar(255) UNIQUE NOT NULL,
  "mat_khau_hash" varchar(255) NOT NULL,
  "ho_ten" varchar(100) NOT NULL,
  "sdt" varchar(20) NOT NULL,
  "vai_tro" varchar(20) NOT NULL
);

CREATE TABLE "khu_vuc" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "ten" varchar(100) NOT NULL,
  "phuong_xa" varchar(100) NOT NULL
);

CREATE TABLE "shipper" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "nguoi_dung_id" int UNIQUE NOT NULL,
  "bien_so" varchar(20) NOT NULL,
  "khu_vuc_phu_trach" int NOT NULL,
  "trang_thai" varchar(30) NOT NULL,
  "so_don_toi_da" int NOT NULL DEFAULT 5 
);

CREATE TABLE "giay_to_shipper" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "shipper_id" int NOT NULL,
  "loai" varchar(50) NOT NULL,
  "so_giay_to" varchar(50) NOT NULL,
  "anh_url" varchar(500),
  "ngay_het_han" date
);

CREATE TABLE "don_giao" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "ma_van_don" varchar(50) UNIQUE NOT NULL,
  "nguoi_gui" varchar(100),
  "dia_chi_lay" text,
  "nguoi_nhan" varchar(100) NOT NULL,
  "sdt_nhan" varchar(20) NOT NULL,
  "dia_chi" text NOT NULL,
  "phuong_xa" int NOT NULL,
  "trong_luong" decimal(10,2),
  "tien_cod" decimal(15,2) DEFAULT 0,
  "shipper_id" int,
  "trang_thai" varchar(30) NOT NULL,
  "han_giao" timestamp NOT NULL,
  "ghi_chu" text
);

CREATE TABLE "ly_do_that_bai" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "ma" varchar(50) UNIQUE NOT NULL,
  "mo_ta" varchar(255) NOT NULL
);

CREATE TABLE "lich_su_trang_thai" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "don_id" int NOT NULL,
  "trang_thai" varchar(30) NOT NULL,
  "thoi_diem" timestamp NOT NULL DEFAULT (now()),
  "nguoi_cap_nhat" int NOT NULL,
  "ly_do_id" int,
  "ghi_chu" text,
  "anh_url" varchar(500)
);

CREATE TABLE "doi_soat_cod" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "shipper_id" int NOT NULL,
  "ngay" date NOT NULL,
  "tong_cod" decimal(15,2) NOT NULL,
  "da_nop" decimal(15,2) NOT NULL,
  "chenh_lech" decimal(15,2) NOT NULL,
  "trang_thai" varchar(30) NOT NULL
);

COMMENT ON COLUMN "nguoi_dung"."vai_tro" IS 'DIEU_PHOI / SHIPPER';

COMMENT ON COLUMN "shipper"."trang_thai" IS 'SAN_SANG / DANG_GIAO / NGHI';

COMMENT ON COLUMN "shipper"."so_don_toi_da" IS 'Máy chủ chặn gán đơn nếu số đơn đang giao vượt mức này';

COMMENT ON COLUMN "giay_to_shipper"."loai" IS 'CCCD / GPLX / DANG_KY_XE';

COMMENT ON COLUMN "don_giao"."nguoi_gui" IS 'Cột mở rộng';

COMMENT ON COLUMN "don_giao"."dia_chi_lay" IS 'Cột mở rộng';

COMMENT ON COLUMN "don_giao"."shipper_id" IS 'Nullable khi đơn mới tạo chưa gán shipper';

COMMENT ON COLUMN "don_giao"."ghi_chu" IS 'Cột mở rộng';

COMMENT ON COLUMN "ly_do_that_bai"."mo_ta" IS 'Danh mục chuẩn: không liên lạc được, khách từ chối, sai địa chỉ...';

COMMENT ON TABLE "lich_su_trang_thai" IS 'Chỉ INSERT thêm dòng mới để lưu vết đầy đủ, tuyệt đối không UPDATE/DELETE dòng cũ';

COMMENT ON COLUMN "lich_su_trang_thai"."ly_do_id" IS 'Cột mở rộng - chỉ điền khi trạng thái là giao thất bại';

ALTER TABLE "shipper" ADD FOREIGN KEY ("nguoi_dung_id") REFERENCES "nguoi_dung" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "shipper" ADD FOREIGN KEY ("khu_vuc_phu_trach") REFERENCES "khu_vuc" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "giay_to_shipper" ADD FOREIGN KEY ("shipper_id") REFERENCES "shipper" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "don_giao" ADD FOREIGN KEY ("phuong_xa") REFERENCES "khu_vuc" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "don_giao" ADD FOREIGN KEY ("shipper_id") REFERENCES "shipper" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "lich_su_trang_thai" ADD FOREIGN KEY ("don_id") REFERENCES "don_giao" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "lich_su_trang_thai" ADD FOREIGN KEY ("nguoi_cap_nhat") REFERENCES "nguoi_dung" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "lich_su_trang_thai" ADD FOREIGN KEY ("ly_do_id") REFERENCES "ly_do_that_bai" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "doi_soat_cod" ADD FOREIGN KEY ("shipper_id") REFERENCES "shipper" ("id") DEFERRABLE INITIALLY IMMEDIATE;

